	`tuition_currency` text,
	`deadline` text,
	`requirements` text,
	`gpa` real,
	`gpa_scale` real,
	`minimum_credits` integer,
	`amount` real,
	`currency` text,
	`source_url` text,
	`verified_at` text,
	`review_due_at` text,
	`status` text,
	`content_hash` text
);
